#!/usr/bin/env node
/**
 * Regenerate db/migrations-bundle.js from db/migrations/*.sql.
 *
 * WHY: the API self-migrates at cold start (src/auto-migrate.js), and on
 * Vercel the serverless function bundle must therefore carry the SQL files.
 * Vercel rejects `includeFiles` inside a `services.*.functions` entry
 * (instant config rejection — the deployment fails before building), so the
 * SQL is embedded in a committed, statically-required CommonJS module
 * instead: require()'d files are ALWAYS traced into the function bundle.
 *
 * Run after adding or editing a migration:
 *   node scripts/bundle-migrations.js
 * Drift is caught by tests/migrations-bundle.test.js (bundle must equal the
 * .sql files byte-for-byte).
 */
'use strict';

const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = path.join(__dirname, '..', 'db', 'migrations');
const OUT_FILE = path.join(__dirname, '..', 'db', 'migrations-bundle.js');

const files = fs.readdirSync(MIGRATIONS_DIR).filter((f) => f.endsWith('.sql')).sort();
if (files.length === 0) {
  console.error('No migration files found.');
  process.exit(1);
}

const map = {};
for (const file of files) {
  map[file] = fs.readFileSync(path.join(MIGRATIONS_DIR, file), 'utf8');
}

const header = `/**
 * AUTO-GENERATED by scripts/bundle-migrations.js — DO NOT EDIT BY HAND.
 *
 * Embedded copy of db/migrations/*.sql for the Vercel function bundle:
 * statically required by src/auto-migrate.js so the migration SQL always
 * ships with the code (Vercel rejects services.*.functions.includeFiles).
 *
 * To change a migration: edit db/migrations/*.sql, then re-run
 * \`node scripts/bundle-migrations.js\`. tests/migrations-bundle.test.js
 * fails when this file drifts from the SQL sources.
 */
'use strict';

module.exports = `;

fs.writeFileSync(OUT_FILE, header + JSON.stringify(map, null, 2) + ';\n');
console.log(`[bundle-migrations] wrote ${OUT_FILE} (${files.length} migrations, ${Object.values(map).reduce((n, s) => n + s.length, 0)} bytes of SQL)`);
